# Called by 14_pooled_robustness.R; conventional stars remain comparable.
fmt <- function(x, digits = 3) formatC(x, format = "f", digits = digits)
stars <- function(p) case_when(
  p < .01 ~ "$^{***}$", p < .05 ~ "$^{**}$",
  p < .10 ~ "$^{*}$", TRUE ~ ""
)
ending <- strrep(intToUtf8(92), 2)
row <- function(label, value) {
  paste(paste(c(label, value), collapse = " & "), ending)
}
lines <- c(
  "% Generated by code/14_pooled_robustness.R",
  "\\begin{table}[!htbp]\\centering",
  "\\caption{Pooled R5--R7 employment IV: robustness comparisons}",
  "\\label{tab:pooledrobustness}",
  "\\linespread{1}\\selectfont",
  "\\begin{threeparttable}\\scriptsize",
  "\\setlength{\\tabcolsep}{4pt}",
  "\\begin{tabular}{lrrr}\\toprule",
  row("", c("No round dummy", "Round dummy",
            "Excl. Amhara")),
  row("", paste0("(", 1:3, ")")), "\\midrule"
)
for (outcome in c("salary_employ", "wage_employ")) {
  s <- stats |> filter(.data$outcome == .env$outcome)
  title <- if (outcome == "salary_employ") {
    "Panel A: Salary employment"
  } else "Panel B: Wage employment"
  lines <- c(lines,
    paste0("\\multicolumn{4}{l}{\\textbf{", title, "}} ", ending),
    row("$MTIuse$", paste0(fmt(s$iv_beta), stars(s$iv_p))),
    row("", paste0("(", fmt(s$iv_se), ")")),
    row("Wild bootstrap SE (dispersion)", fmt(s$wild_boot_se)),
    row("Wild bootstrap $p$ (W-B-S)", fmt(s$wild_boot_p)),
    row("Wild AR score $p$ (weak-IV robust)", fmt(s$AR_p_sign_beta0)),
    row("Regional CR2 SE", fmt(s$iv_se_CR2)),
    row("Regional CR2/Satt. $p$", fmt(s$iv_p_CR2)),
    row("First-stage excluded-IV $F$", fmt(s$first_stage_F, 2)),
    row("Round dummy", ifelse(s$round_dummy, "Yes", "No")),
    row("Cohort dummy", ifelse(s$cohort_dummy, "Yes", "No")),
    row("Regions", s$clusters),
    row("Rademacher sign patterns", s$wild_patterns),
    row("Observations", s$n), "\\midrule"
  )
}
lines <- c(lines,
  "\\bottomrule\\end{tabular}",
  "\\begin{tablenotes}\\scriptsize",
  "\\item All columns pool R5 older and R7 both cohorts; R7 in person only.",
  "All models use the fixed baseline-reduced sample and cohort indicators.",
  "Column 1 omits the round indicator. Column 3 excludes Amhara.",
  "Controls use current R7 household resources and original R3 resources",
  "in R5 rows. MTI is frozen at R5; YC exposure remains exploratory.",
  "Salary=13; combined farm/nonfarm wage=5--7/12/19.",
  "R5 first-ranked and R7 annual main activity define all employment outcomes.",
  "R5 non-interviews, unknown first types and other work are excluded.",
  "\\item Parentheses and stars use conventional inference:",
  "*** $p<0.01$, ** $p<0.05$, * $p<0.10$.",
  "Wild bootstrap follows Wang--Zhang (2024), Algorithm 1 (2SLS),",
  "with region-interacted first-stage instruments and all 16 or 8",
  "Rademacher patterns. W-B-S imposes beta=0 and studentizes each draw.",
  "SE is the dispersion of unrestricted-centred coefficient draws,",
  "not a calibrated small-cluster Wald correction; use bootstrap p-values.",
  "Wild AR score tests beta=0 after within-region instrument residualization",
  "and discards between-region variation (see saved method notes).",
  "\\item Regional clustering keeps repeated IDs in the same cluster.",
  "With only 4 or 3 regions, bootstrap inference is coarse and is not",
  "an automatic correction: independent clusters and additional regularity",
  "conditions are required. Stars are not based on bootstrap inference.",
  "\\end{tablenotes}\\end{threeparttable}\\end{table}"
)
file <- "output/tables/table_pooled_robustness.tex"
writeLines(lines, file)
mirror_output(file, "tables")
